public sealed class Duration
{
    public static Duration FromSeconds(double s) => new Duration(TimeSpan.FromSeconds(s));
    public static Duration FromMinutes(double m) => new Duration(TimeSpan.FromMinutes(m));
    public static Duration Parse(string text) => new Duration(TimeSpan.Parse(text));  // may throw
    private Duration(TimeSpan value) => Value = value;
    public TimeSpan Value { get; }
}
